const input = $input.first().json || {};
const runType = String(input.requestedRunType || input.runType || '').toUpperCase();
const cfg = input.centralConfig || {};
const globalCfg = cfg.globalConfig || {};
const channels = cfg.channels || {};
const groqApiKey = globalCfg.groqApiKey || '';
const groqModel = globalCfg.groqModel || 'llama-3.3-70b-versatile';
const mainOfferUrl = globalCfg.mainOfferUrl || '';
const emailCaptureUrl = globalCfg.emailCaptureUrl || mainOfferUrl;
const channelKey = input.channelKey || 'localStackAi';
const channel = channels[channelKey] || {};
const niche = channel.niche || 'AI automation for local businesses';
const nicheKeywords = channel.nicheKeywords || 'local business automation';
const offerCatalog = channel.offerCatalog || [];
const isDemo = !groqApiKey || groqApiKey === '' || groqApiKey.startsWith('demo-');
const supported = ['CONTENT_DAILY', 'DRAFT_MINING', 'CONTENT_SHORTS'];
if (!supported.includes(runType)) {
  return [{ json: { ...input, status: 'CONTENT_SKIPPED', contentSummary: 'Unsupported content runType: ' + (runType || 'UNKNOWN'), completedAt: new Date().toISOString() } }];
}
const topics = nicheKeywords.split(',').map(k => k.trim()).filter(Boolean);
const focusTopic = topics[Math.floor(Math.random() * topics.length)] || niche;
const ctaTemplates = offerCatalog.length > 0
  ? offerCatalog.map(o => ({ label: o.label, cta: o.cta || 'Get it free', shortsCta: o.shortsCta || (o.cta + ' -> link in bio') || 'Get it free -> link in bio', url: o.url || mainOfferUrl, fit: o.fit || [] }))
  : [
      { label: 'Free Guide', cta: 'Get the free stack guide', shortsCta: 'Free guide -> link in bio', url: mainOfferUrl, fit: ['all'] },
      { label: 'Email Course', cta: 'Get 5 free templates by email', shortsCta: '5 free templates -> link in bio', url: emailCaptureUrl, fit: ['all'] }
    ];
const primaryCta = ctaTemplates[0] || { cta: 'Get the free guide', shortsCta: 'Free guide -> link in bio', url: mainOfferUrl };
const systemPrompt = 'You are a YouTube content strategist for a channel about: ' + niche + '. Rules: ALWAYS optimise titles for CTR. ALWAYS include a pain-point hook. NEVER be vague. Output valid JSON only.';
let userPrompt = '';
if (runType === 'CONTENT_DAILY') {
  userPrompt = 'Generate a YouTube long-form content plan for today video about "' + focusTopic + '". Return JSON with these exact keys: title (string, 60 chars max, curiosity/benefit hook), titleVariants (array of 3 A/B test titles), description (string, 250 chars, include keyword and CTA), tags (array of 10 SEO tags), thumbnailIdea (string), shortScript (string, 60-second Shorts hook using first 3 sentences), openingHook (string, first spoken sentence under 15 words), estimatedCtr (string, e.g. 8-12%), bestPostTime (string), pinnedComment (string, CTA with offer link).';
} else if (runType === 'CONTENT_SHORTS') {
  userPrompt = 'Generate a YouTube Shorts script for niche: "' + niche + '", topic: "' + focusTopic + '". Return JSON with these exact keys: hook (string, first 3 words that stop scroll), script (string, 60-second punchy spoken script), callToAction (string), hashtags (array of 5), thumbnailText (string, 3 words max for thumbnail overlay).';
} else {
  userPrompt = 'Mine 5 high-opportunity video ideas for channel niche: "' + niche + '". Return JSON with key "ideas" containing array of objects each with: title, searchVolumeTier (high/medium/low), competitionTier (low/medium/high), gapScore (integer 0-100), keywordFocus, revenueRelevance, offerFit.';
}
let contentData = null;
let aiStatus = 'DEMO';
if (!isDemo) {
  try {
    const resp = await fetch('https://api.groq.com/openai/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + groqApiKey },
      body: JSON.stringify({ model: groqModel, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }], temperature: 0.7, max_tokens: 1400, response_format: { type: 'json_object' } })
    });
    if (!resp.ok) throw new Error('Groq ' + resp.status + ': ' + (await resp.text()).slice(0, 300));
    const groqResp = await resp.json();
    const raw = groqResp.choices?.[0]?.message?.content || '{}';
    contentData = JSON.parse(raw);
    aiStatus = 'GROQ_LIVE';
  } catch(e) {
    contentData = { _groqError: String(e.message || e) };
    aiStatus = 'GROQ_ERROR';
  }
}
if (!contentData || aiStatus === 'DEMO') {
  if (runType === 'CONTENT_DAILY') {
    contentData = {
      title: 'How to automate ' + focusTopic + ' (no tech skills needed)',
      titleVariants: [
        focusTopic + ': the automation most local businesses skip',
        'Save 5h/week: automate ' + focusTopic + ' today',
        'The free ' + focusTopic + ' system that runs itself'
      ],
      description: 'Stop doing ' + focusTopic + ' manually. I show the exact stack saving local service businesses time and money. ' + primaryCta.cta + ': ' + primaryCta.url,
      tags: [focusTopic, 'local business automation', 'AI tools', 'small business', 'no-code', 'automation', 'save money', 'CRM', 'workflow', niche],
      thumbnailIdea: 'Split: BEFORE (exhausted owner) vs AFTER (phone: new booking confirmed). Large bold text overlay.',
      shortScript: 'Most ' + focusTopic + ' is still done manually and it costs local businesses 5+ hours a week. There is a free stack that replaces it in 10 minutes. Here is exactly how.',
      openingHook: 'You are losing 5 hours every week to something you could automate for free.',
      estimatedCtr: '7-11%',
      bestPostTime: 'Tue/Thu 10am or 7pm viewer timezone',
      pinnedComment: primaryCta.cta + ' -> ' + primaryCta.url
    };
  } else if (runType === 'CONTENT_SHORTS') {
    contentData = {
      hook: 'STOP paying for',
      script: 'STOP paying for ' + focusTopic + ' tools when there is a free stack that does the same job. Step 1: replace your CRM with a free plan. Step 2: connect your booking link. Step 3: automate follow-up texts. Total cost: $0. Follow for the full tutorial.',
      callToAction: primaryCta.shortsCta,
      hashtags: ['#localbusiness', '#automation', '#aitools', '#smallbusiness', '#nocode'],
      thumbnailText: '$0 ' + (focusTopic.split(' ')[0] || 'SETUP')
    };
  } else {
    contentData = { ideas: [
      { title: focusTopic + ' automation for ' + (channel.channelName || 'local businesses'), searchVolumeTier: 'high', competitionTier: 'low', gapScore: 82, keywordFocus: focusTopic, revenueRelevance: 'high', offerFit: (offerCatalog[0] || {}).label || 'guide' },
      { title: 'Replace expensive CRM with free ' + focusTopic + ' stack', searchVolumeTier: 'medium', competitionTier: 'low', gapScore: 78, keywordFocus: 'CRM alternative', revenueRelevance: 'high', offerFit: (offerCatalog[0] || {}).label || 'guide' },
      { title: 'How service businesses automate bookings with ' + focusTopic, searchVolumeTier: 'high', competitionTier: 'medium', gapScore: 74, keywordFocus: 'booking automation', revenueRelevance: 'medium', offerFit: (offerCatalog[1] || {}).label || 'playbook' },
      { title: focusTopic + ': step-by-step for plumbers cleaners and contractors', searchVolumeTier: 'medium', competitionTier: 'low', gapScore: 71, keywordFocus: 'trade business automation', revenueRelevance: 'high', offerFit: (offerCatalog[0] || {}).label || 'guide' },
      { title: '5 ' + focusTopic + ' tools most local businesses do not know exist (all free)', searchVolumeTier: 'high', competitionTier: 'low', gapScore: 88, keywordFocus: 'free tools local business', revenueRelevance: 'high', offerFit: (offerCatalog[0] || {}).label || 'guide' }
    ]};
  }
}
return [{ json: {
  ...input,
  status: 'CONTENT_COMPLETE',
  aiStatus,
  runType,
  channelKey,
  contentData,
  ctaTemplates,
  contentSummary: 'Content pipeline completed for ' + runType + ' [' + aiStatus + '] on ' + channelKey,
  completedAt: new Date().toISOString(),
  workflowPackVersion: input.workflowPackVersion || 'v24'
} }];
